(async () => {
  const out = { path: location.pathname };
  out.title = document.querySelector('.pj-title')?.textContent || null;
  out.crumb = (document.querySelector('.pj-crumb')?.innerText || '').replace(/\s+/g, ' ');
  out.headActions = [...document.querySelectorAll('.pj-head-actions button')].map((b) => b.textContent.trim()).filter(Boolean).join(' | ');
  out.cards = document.querySelectorAll('.pj-card').length;
  const txt = document.body.innerText || '';
  out.hasRecommend = txt.includes('相关项目推荐');
  out.hasBom = txt.includes('元器件清单');
  out.hasDesc = txt.includes('项目描述');
  out.hasTutorial = txt.includes('图文教程') || txt.includes('注意事项');
  out.siteNav = [...document.querySelectorAll('header a')].map((a) => a.textContent.trim()).filter(Boolean).join('/');
  out.infoRows = (document.querySelector('.pj-info')?.innerText || '').replace(/\s+/g, ' ');
  out.meta = (document.querySelector('.pj-meta')?.innerText || '').replace(/\s+/g, ' ');
  out.aiRing = (document.querySelector('.pj-head-ring')?.innerText || '').replace(/\s+/g, ' ');
  return JSON.stringify(out);
})()
